<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,nextTick} from 'vue';
import type {ValueChoice} from '../lib/field-values';
const props=defineProps<{id:string;name:string;choices:ValueChoice[];rules:string[];codeLabel:string;nameLabel:string;readonly:boolean;field:HTMLElement|null;query:string;selection:boolean}>();
const emit=defineEmits<{close:[];select:[key:string]}>(),box=ref<HTMLElement>(),position=ref({});let observer:ResizeObserver|undefined;
const normalize=(value:string)=>value.trim().normalize('NFKC').toLocaleLowerCase();
const rows=computed(()=>props.choices.filter(c=>normalize(c.code+' '+c.name).includes(normalize(props.query))));
function place(){if(!props.field)return;const r=props.field.getBoundingClientRect(),width=Math.min(Math.max(r.width,280),innerWidth-24),left=Math.max(12,Math.min(r.left,innerWidth-width-12)),below=innerHeight-r.bottom-12,above=r.top-12,up=below<160&&above>below;position.value={left:left+'px',width:width+'px',maxHeight:Math.min(320,Math.max(80,up?above:below))+'px',...(up?{bottom:innerHeight-r.top+'px'}:{top:r.bottom+'px'})};}
function choose(row:ValueChoice){if(!props.readonly&&!row.disabled)emit('select',row.key);}
function outside(event:Event){const n=event.target as Node;if(!box.value?.contains(n)&&!props.field?.closest('.field-label')?.contains(n))emit('close');}
function keyboard(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('close');props.field?.focus();}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)&&box.value?.contains(event.target as Node)){event.preventDefault();const buttons=Array.from(box.value.querySelectorAll<HTMLButtonElement>('.field-value-choice:not(:disabled)')),index=buttons.indexOf(document.activeElement as HTMLButtonElement),next=event.key==='Home'?0:event.key==='End'?buttons.length-1:Math.max(0,Math.min(buttons.length-1,index+(event.key==='ArrowDown'?1:-1)));buttons[next]?.focus();}}
onMounted(async()=>{await nextTick();place();observer=new ResizeObserver(place);if(props.field)observer.observe(props.field);document.addEventListener('pointerdown',outside);document.addEventListener('keydown',keyboard,true);window.addEventListener('resize',place);window.addEventListener('scroll',place,true);});
onBeforeUnmount(()=>{observer?.disconnect();document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',keyboard,true);window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true);});
</script>
<template><Teleport :to="field?.closest('dialog[open]')??'body'"><section ref="box" :id="id" class="field-value-popup" :style="position" @mousedown.prevent :aria-label="name+(selection?'候选项':'说明')">
 <table v-if="selection" class="field-value-table"><thead><tr><th scope="col">{{ codeLabel }}</th><th scope="col">{{ nameLabel }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.key" :class="{selected:row.selected,unavailable:readonly||row.disabled}" @click="choose(row)"><td><button type="button" class="field-value-choice" :disabled="readonly||row.disabled" :aria-label="'选择 '+row.name+'（'+row.code+'）'" @click.stop="choose(row)" @keydown.enter.prevent="choose(row)">{{ row.code }}</button></td><td>{{ row.name }}</td></tr><tr v-if="!rows.length"><td colspan="2" class="field-value-empty">没有匹配的候选项</td></tr></tbody></table>
 <div v-else class="field-note-popup"><h3>{{ name }} · 说明</h3><p v-for="rule in rules" :key="rule">{{ rule }}</p><button type="button" @click="emit('close');field?.focus()">关闭说明</button></div>
</section></Teleport></template>
<style>
.field-value-popup{position:fixed;z-index:60;overflow:auto;overscroll-behavior:contain;background:var(--paper);border:1px solid #8a969f;border-radius:10px;box-shadow:0 3px 8px #29384629;color:#516b82}.field-value-table{font-size:14px;table-layout:fixed}.field-value-table th{position:sticky;top:0;background:var(--paper);z-index:1;color:#243745;font-size:14px;font-weight:600;padding:10px 18px;border-bottom:1px solid #dce0e3}.field-value-table th:first-child{width:32%}.field-value-table td{padding:0 18px;border:0;vertical-align:middle;overflow-wrap:anywhere}.field-value-table td:first-child{padding:0}.field-value-table tr{cursor:pointer}.field-value-table tr:hover,.field-value-table tr.selected{background:#e9f2fc}.field-value-table tr.unavailable{cursor:default;color:#7c8996}.field-value-table .field-value-choice{display:block;width:100%;text-align:left;white-space:normal;border:0;border-radius:0;margin:0;padding:10px 18px;min-height:42px;font-size:14px;background:transparent;color:inherit}.field-value-choice:focus-visible{outline:2px solid #0868c9;outline-offset:-2px}.field-value-table .field-value-empty{padding:12px 18px;color:var(--muted)}.field-note-popup{padding:16px;font-size:13px;line-height:1.7;color:var(--ink)}.field-note-popup h3{font-size:14px;margin:0 0 10px}.field-note-popup p{margin-bottom:8px}.field-note-popup button{color:#0868c9;border:0;background:transparent;padding:4px 0}@media(max-width:560px){.field-value-table th:first-child{width:38%}.field-value-table th,.field-value-table td{padding-left:12px;padding-right:12px}.field-value-table .field-value-choice{padding-left:12px;padding-right:12px;min-height:44px}}
</style>
